import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { FiSearch, FiShoppingCart, FiUser, FiLogOut, FiChevronDown, FiHeart, FiArrowLeft } from 'react-icons/fi';
import { useShopCart } from '../../ShopCartContext';
import UnifiedAuthModalSeller from '../../UnifiedAuthModalSeller';
import { logoutUser, logoutSeller, logoutCentre, clearAllSessions } from '../../../utils/authSession';

const HeaderShop = ({ initialSearchQuery = "" }) => {
  const [query, setQuery] = useState(initialSearchQuery);
  const [user, setUser] = useState(null);
  console.log("user in header", user);
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);
  const [hoveredCategory, setHoveredCategory] = useState(null);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const { shopCartItems } = useShopCart();
  const navigate = useNavigate();
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isMobileCategoryMenuOpen, setIsMobileCategoryMenuOpen] = useState(false);
  const [expandedMobileCat, setExpandedMobileCat] = useState("pharmacy");
  const [mobileCategory, setMobileCategory] = useState(null);
  const isCartPage = location.pathname.startsWith('/medicine/cart') || location.pathname === '/cart';

  const isEcommerceRoute = (pathname) => {
    if (!pathname) return false;
    const path = pathname.toLowerCase();
    if (
      path.startsWith('/shop') ||
      path.startsWith('/all-products') ||
      path.startsWith('/all-sellers') ||
      path.startsWith('/seller') ||
      path.startsWith('/medicine') ||
      path.startsWith('/pharmacy') ||
      path.startsWith('/medical-instruments') ||
      path.startsWith('/health-product')
    ) {
      return true;
    }
    const segments = path.split('/').filter(Boolean);
    if (segments.length === 2) {
      const first = segments[0];
      const knownHealthcare = [
        'service',
        'package',
        'edit-doctor',
        'edit-service',
        'edit-package',
        'centre-dashboard',
        'user-dashboard',
        'admin-dashboard',
        'admin'
      ];
      if (!knownHealthcare.includes(first)) {
        return true;
      }
    }
    return false;
  };

  const [activeTab, setActiveTab] = useState(
    isEcommerceRoute(location.pathname) ? 'ecommerce' : 'healthcare'
  );

  useEffect(() => {
    setActiveTab(isEcommerceRoute(location.pathname) ? 'ecommerce' : 'healthcare');
  }, [location.pathname]);

  const handleTabClick = (tab) => {
    setActiveTab(tab);
    if (tab === "ecommerce") {
      if (!isEcommerceRoute(location.pathname)) {
        navigate("/shop");
      }
    } else {
      if (isEcommerceRoute(location.pathname)) {
        navigate("/");
      }
    }
  };

  // Parse active category/subcategory from URL to show active states
  const queryParams = new URLSearchParams(location.search);
  const activeCategory = queryParams.get('category') || '';
  const activeSubCategory = queryParams.get('subCategory') || '';

  useEffect(() => {
    setQuery(initialSearchQuery);
  }, [initialSearchQuery]);

  // Automatically trigger search when query length > 2 or when cleared
  useEffect(() => {
    const trimmed = query.trim();
    const currentParam = new URLSearchParams(location.search).get('search') || '';

    if (trimmed === currentParam.trim()) return;

    const timer = setTimeout(() => {
      if (trimmed.length > 2 || trimmed.length === 0) {
        navigate(`/all-products?search=${encodeURIComponent(trimmed)}`);
      }
    }, 400);

    return () => clearTimeout(timer);
  }, [query, location.search, navigate]);

  const loadUser = () => {
    const storedUser = localStorage.getItem("user");
    const storedCentre = localStorage.getItem("centre");
    const storedSeller = localStorage.getItem("seller");
    if (storedUser) {
      try {
        const parsed = JSON.parse(storedUser);
        const name = parsed.name || `${parsed.firstName || ''} ${parsed.lastName || ''}`.trim() || parsed.email || "User";
        setUser({ ...parsed, name });
      } catch (e) {
        setUser(null);
      }
    } else if (storedCentre) {
      try {
        setUser(JSON.parse(storedCentre));
      } catch (e) {
        setUser(null);
      }
    } else if (storedSeller) {
      try {
        const parsedSeller = JSON.parse(storedSeller);
        const sellerName = parsedSeller.basicInformation?.shopName || parsedSeller.basicInformation?.contactPersonName || parsedSeller.name || "Seller";
        setUser({
          ...parsedSeller,
          name: sellerName,
          role: "seller"
        });
      } catch (e) {
        setUser(null);
      }
    } else {
      setUser(null);
    }
  };

  useEffect(() => {
    loadUser();
    window.addEventListener("userLogin", loadUser);
    window.addEventListener("storage", loadUser);
    return () => {
      window.removeEventListener("userLogin", loadUser);
      window.removeEventListener("storage", loadUser);
    };
  }, []);

  const handleSearchSubmit = (e) => {
    if (e) e.preventDefault();
    navigate(`/all-products?search=${encodeURIComponent(query.trim())}`);
  };

  const handleLogout = () => {
    setShowProfileDropdown(false);
    if (localStorage.getItem("sellerToken") || user?.role === "seller") {
      logoutSeller({ reason: "manual", navigate });
    } else if (localStorage.getItem("userToken") || user) {
      logoutUser({ reason: "manual", navigate });
    } else if (localStorage.getItem("centreToken")) {
      logoutCentre({ reason: "manual", navigate });
    } else {
      clearAllSessions();
      setUser(null);
      navigate("/");
    }
    setUser(null);
  };

  const handleMouseEnter = (catId) => {
    if (window.innerWidth >= 992) {
      setHoveredCategory(catId);
    }
  };

  const handleCategoryClick = (cat, e) => {
    if (e) {
      e.stopPropagation();
    }
    // Clicking category text directly selects the category
    handleSelectCategory(cat.name, "All");
    setHoveredCategory(null);
  };

  const handleCategoryIconClick = (cat, e) => {
    if (e) {
      e.stopPropagation();
    }
    // Tapping the category icon beside the category name opens/closes the subcategories sheet
    if (hoveredCategory === cat.id) {
      setHoveredCategory(null);
    } else {
      setHoveredCategory(cat.id);
    }
  };

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (
        !e.target.closest(".header-category-item") &&
        !e.target.closest(".header-subcat-dropdown") &&
        !e.target.closest(".header-mobile-sheet-container")
      ) {
        setHoveredCategory(null);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleSelectCategory = (category, subCategory) => {
    const apiCategory = category === "Medicines & Cosmetics" ? "Medicines" : category;
    if (!subCategory || subCategory === "All" || subCategory.startsWith("All")) {
      navigate(`/all-products?category=${encodeURIComponent(apiCategory)}`);
    } else {
      navigate(`/all-products?category=${encodeURIComponent(apiCategory)}&subCategory=${encodeURIComponent(subCategory)}`);
    }
  };

  const categories = [
    {
      id: "pharmacy",
      name: "Medicines & Cosmetics",
      subCategories: [
        "Homeopathy",
        "Personal Care Products",
        "Ayurveda Products",
        "Stomach Care",
        "Health Conditions",
        "Winter Care Essentials",
        "Skin Care",
        "Diabetes",
        "Baby Care",
        "Hair Care",
        "Sexual Wellness",
        "Covid Essentials",
        "Elderly Care",
        "Summer Essentials",
        "Pain Relief",
        "Anti-Pollution",
        "Air Pollution",
        "Personal Care",
        "Feminine Care",
        "Monsoon Essentials",
        "Fever & Headache",
        "Eye & Ear Care",
        "Skin, Hair & Oral Care",
        "Cold, Cough & Fever",
        "Skin Infection",
        "Featured"
      ]
    },
    {
      id: "medical-equipment",
      name: "Medical devices & surgical equipment",
      subCategories: [
        "Healthcare Devices",
        "Supports & Braces",
        "Monitoring Devices",
        "First Aid"
      ]
    },
    {
      id: "health-supplements",
      name: "Health Supplements",
      subCategories: [
        "Vitamins & Nutrition",
        "Fitness Supplements",
        "Multivitamins",
        "Nutritional Drinks",
        "Immunity Boosters",
        "Herbal Juice",
        "Healthy Snacks",
        "Food & Beverages",
        "Rehydration Beverages",
        "Fitness & Health"
      ]
    },
    {
      id: "pet-care",
      name: "Pet Care",
      subCategories: []
    },
    {
      id: "other",
      name: "Others",
      subCategories: []
    }
  ];

  return (
    <div style={{ position: 'sticky', top: 0, zIndex: 9999, backgroundColor: '#ffffff', boxShadow: '0 4px 12px rgba(0, 0, 0, 0.03)' }}>
      {/* Top Header Switcher Bar: E-Commerce & HealthCare */}
      <div className="d-flex align-items-center justify-content-center gap-2 gap-md-3 py-2 px-3 border-bottom" style={{ backgroundColor: "#F8FAFC" }}>
        <button
          type="button"
          onClick={() => handleTabClick("ecommerce")}
          style={{
            backgroundColor: activeTab === "ecommerce" ? "#6D28D9" : "#FFFFFF",
            color: activeTab === "ecommerce" ? "#FFFFFF" : "#6D28D9",
            border: activeTab === "ecommerce" ? "none" : "1.5px solid #DDD6FE",
            borderRadius: "50px",
            padding: "6px 18px",
            fontSize: "13px",
            fontWeight: "700",
            display: "inline-flex",
            alignItems: "center",
            gap: "6px",
            boxShadow: activeTab === "ecommerce" ? "0 3px 10px rgba(109, 40, 217, 0.2)" : "none",
            cursor: "pointer",
            transition: "all 0.25s ease"
          }}
        >
          <FiShoppingCart size={15} color={activeTab === "ecommerce" ? "#FFFFFF" : "#6D28D9"} />
          <span>Online Pharmacy</span>
        </button>

        <button
          type="button"
          onClick={() => handleTabClick("healthcare")}
          style={{
            backgroundColor: activeTab === "healthcare" ? "#6D28D9" : "#FFFFFF",
            color: activeTab === "healthcare" ? "#FFFFFF" : "#6D28D9",
            border: activeTab === "healthcare" ? "none" : "1.5px solid #DDD6FE",
            borderRadius: "50px",
            padding: "6px 18px",
            fontSize: "13px",
            fontWeight: "700",
            display: "inline-flex",
            alignItems: "center",
            gap: "6px",
            boxShadow: activeTab === "healthcare" ? "0 3px 10px rgba(109, 40, 217, 0.2)" : "none",
            cursor: "pointer",
            transition: "all 0.25s ease"
          }}
        >
          <FiHeart size={15} color={activeTab === "healthcare" ? "#FFFFFF" : "#6D28D9"} />
          <span>Healthcare</span>
        </button>
      </div>

      {/* Top Header Row */}
      <header style={{
        borderBottom: '1px solid #F1F5F9',
        padding: '12px 4%'
      }}>
        <div className="header-top-container">
          {/* Logo Section */}
          <div className="header-logo">
            <Link to="/shop" style={{ display: 'flex', alignItems: 'center' }}>
              <img
                src="/assets/images/logo/BHARATLOGO-011.webp"
                alt="4ceps Logo"
                style={{ height: '50px', width: 'auto', objectFit: 'contain' }}
              />
            </Link>
          </div>

          {/* Center Search Bar & Mobile Category Dropdown Button */}
          <div className={`header-search-wrapper ${isCartPage ? 'cart-page-search-hidden' : ''}`}>
            <form
              onSubmit={handleSearchSubmit}
              className="header-search-form"
            >
              <input
                type="text"
                placeholder="Search medicines, equipment, beauty..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                style={{
                  border: 'none',
                  outline: 'none',
                  backgroundColor: 'transparent',
                  width: '100%',
                  fontSize: '14px',
                  color: '#1E293B',
                  padding: '6px 0'
                }}
              />
              <button
                type="submit"
                style={{
                  backgroundColor: '#A847F0',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '50%',        // Changed from '50px' to '50%' for perfect circle
                  width: '38px',              // Added fixed width
                  height: '38px',             // Added fixed height
                  display: 'flex',            // Added for centering icon
                  alignItems: 'center',       // Added for centering icon
                  justifyContent: 'center',   // Added for centering icon
                  cursor: 'pointer',
                  transition: 'background-color 0.2s',
                  flexShrink: 0,
                  padding: 0                  // Added to remove default padding
                }}
                onMouseEnter={(e) => e.target.style.backgroundColor = '#8B35D4'}
                onMouseLeave={(e) => e.target.style.backgroundColor = '#A847F0'}
              >
                <FiSearch size={18} color="#ffffff" />  {/* Only the icon, no text */}
              </button>
            </form>

            {/* Mobile Category Dropdown Icon Button - AFTER search input field, ONLY on mobile (< 992px) */}
            <button
              type="button"
              className="d-flex d-lg-none mobile-category-dropdown-btn"
              onClick={() => setIsMobileCategoryMenuOpen(!isMobileCategoryMenuOpen)}
              title="Categories Menu"
              aria-label="Open Categories Menu"
              style={{
                backgroundColor: isMobileCategoryMenuOpen ? '#7C3AED' : '#F1F5F9',
                color: isMobileCategoryMenuOpen ? '#FFFFFF' : '#475569',
                border: isMobileCategoryMenuOpen ? '1.5px solid #7C3AED' : '1.5px solid #CBD5E1',
                borderRadius: '50%',
                width: '38px',
                height: '38px',
                minWidth: '38px',
                alignItems: 'center',
                justifyContent: 'center',
                cursor: 'pointer',
                flexShrink: 0,
                marginLeft: '8px',
                transition: 'all 0.2s ease',
                boxShadow: isMobileCategoryMenuOpen ? '0 2px 8px rgba(124, 58, 237, 0.3)' : 'none'
              }}
            >
              <FiChevronDown
                size={19}
                style={{
                  transition: 'transform 0.25s ease',
                  transform: isMobileCategoryMenuOpen ? 'rotate(180deg)' : 'rotate(0deg)'
                }}
              />
            </button>
          </div>

          {/* Right Actions */}
          <div className="header-actions">
            {/* Cart Icon */}
            <Link
              to="/medicine/cart"
              style={{
                position: 'relative',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: '42px',
                height: '42px',
                borderRadius: '50%',
                backgroundColor: '#F8FAFC',
                color: '#475569',
                transition: 'all 0.2s ease',
                textDecoration: 'none'
              }}
            >
              <FiShoppingCart size={20} />
              {shopCartItems.length > 0 && (
                <span style={{
                  position: 'absolute',
                  top: '-4px',
                  right: '-4px',
                  backgroundColor: '#A847F0',
                  color: '#ffffff',
                  fontSize: '11px',
                  fontWeight: '700',
                  borderRadius: '50%',
                  width: '18px',
                  height: '18px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  boxShadow: '0 2px 4px rgba(168, 71, 240, 0.3)'
                }}>
                  {shopCartItems.length}
                </span>
              )}
            </Link>

            {/* Login / Profile Dropdown */}
        {user && (user.role === "seller" || user.role === "User") ? (
  <div style={{ position: 'relative' }}>
    {/* Profile Button */}
    <button
      onClick={() => setShowProfileDropdown(!showProfileDropdown)}
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: '8px',
        border: 'none',
        background: 'none',
        cursor: 'pointer',
        padding: '6px 12px',
        borderRadius: '20px',
        backgroundColor: '#F8FAFC',
        color: '#1E293B',
        fontWeight: '600',
        fontSize: '14px'
      }}
    >
      <FiUser size={16} color="#A847F0" />
      <span>
        {user.name ? user.name.split(" ")[0] : "Profile"}
      </span>
    </button>

    {showProfileDropdown && (
      <div
        style={{
          position: 'absolute',
          top: '100%',
          right: 0,
          marginTop: '10px',
          backgroundColor: '#ffffff',
          border: '1px solid #E2E8F0',
          borderRadius: '12px',
          boxShadow: '0 10px 25px rgba(0, 0, 0, 0.08)',
          width: '180px',
          zIndex: 10000,
          padding: '6px 0',
          textAlign: 'left'
        }}
      >
        <Link
          to={
            user.role === "seller"
              ? "/seller-dashboard"
              : "/user-dashboard"
          }
          onClick={() => setShowProfileDropdown(false)}
          style={{
            display: 'block',
            padding: '10px 16px',
            fontSize: '14px',
            color: '#334155',
            textDecoration: 'none',
            fontWeight: '500',
            textDecoration: 'none'
          }}
        >
          Dashboard
        </Link>

        <button
          onClick={handleLogout}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '8px',
            width: '100%',
            border: 'none',
            background: 'none',
            padding: '10px 16px',
            fontSize: '14px',
            color: '#EF4444',
            cursor: 'pointer',
            textAlign: 'left',
            fontWeight: '500',
            borderTop: '1px solid #F1F5F9'
          }}
        >
          <FiLogOut size={14} />
          <span>Logout</span>
        </button>
      </div>
    )}
  </div>
) : !user ? (
  // Show Login / Sign Up only when user is NOT logged in
  <button
    onClick={() => setIsLoginModalOpen(true)}
    style={{
      display: 'flex',
      alignItems: 'center',
      gap: '6px',
      backgroundColor: '#1E293B',
      color: '#ffffff',
      border: 'none',
      borderRadius: '50px',
      padding: '10px 20px',
      fontSize: '14px',
      fontWeight: '600',
      textDecoration: 'none',
      cursor: 'pointer',
      transition: 'background-color 0.2s'
    }}
    onMouseEnter={(e) =>
      e.target.style.backgroundColor = '#0F172A'
    }
    onMouseLeave={(e) =>
      e.target.style.backgroundColor = '#1E293B'
    }
  >
    <FiUser size={16} />
    <span>Login / Sign Up</span>
  </button>
) : null}
          </div>
        </div>
      </header>

      {/* Category Navigation Bar - Visible on Desktop/Tablet, Hidden on Mobile */}
      <nav
        className={`header-category-nav-bar d-none d-lg-block ${isCartPage ? 'cart-page-nav-hidden' : ''}`}
        style={{
          borderBottom: '1px solid #E2E8F0',
          padding: '0 4%',
          position: 'relative'
        }}
      >
        <div className="header-category-nav-container" style={{ height: '48px' }}>
          {categories.map((cat) => {
            const normalizedCategory =
              activeCategory === "Medicines"
                ? "Medicines & Cosmetics"
                : activeCategory;

            const isCatActive = normalizedCategory === cat.name;

            return (
              <div
                key={cat.id}
                className="header-category-item"
                style={{ position: 'relative', height: '100%', display: 'flex', alignItems: 'center' }}
                onMouseEnter={() => {
                  if (window.innerWidth >= 992 && !["pet-care", "other"].includes(cat.id)) {
                    handleMouseEnter(cat.id);
                  }
                }}
                onMouseLeave={() => {
                  if (window.innerWidth >= 992 && !["pet-care", "other"].includes(cat.id)) {
                    setHoveredCategory(null);
                  }
                }}
              >
                {/* Category Link */}
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '4px',
                    color: isCatActive ? '#A847F0' : '#475569',
                    fontWeight: '600',
                    fontSize: '15px',
                    height: '100%',
                    borderBottom: isCatActive ? '2px solid #A847F0' : '2px solid transparent',
                    padding: '0 4px',
                    transition: 'all 0.2s ease',
                  }}
                >
                  <span
                    onClick={(e) => handleCategoryClick(cat, e)}
                    style={{ cursor: 'pointer', whiteSpace: 'nowrap', padding: '4px 0' }}
                  >
                    {cat.name}
                  </span>

                  {/* Show dropdown icon only when there are actual subcategories (Clicking icon opens mobile menu) */}
                  {!["pet-care", "other"].includes(cat.id) && cat.subCategories && cat.subCategories.length > 0 && (
                    <span
                      className="header-category-icon-btn"
                      onClick={(e) => handleCategoryIconClick(cat, e)}
                      title={`View ${cat.name} subcategories`}
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        padding: '6px 5px',
                        cursor: 'pointer',
                        borderRadius: '4px',
                        userSelect: 'none'
                      }}
                    >
                      <FiChevronDown
                        size={15}
                        style={{
                          transition: 'transform 0.2s',
                          transform:
                            hoveredCategory === cat.id ? 'rotate(180deg)' : 'rotate(0deg)'
                        }}
                      />
                    </span>
                  )}
                </div>

                {/* Subcategories Dropdown Menu for Desktop */}
                {!["pet-care", "other"].includes(cat.id) && cat.subCategories && cat.subCategories.length > 0 &&
                  hoveredCategory === cat.id && (
                    <div
                      className="header-subcat-dropdown d-none d-lg-block custom-dropdown-scroll"
                      style={{
                        position: 'absolute',
                        top: '100%',
                        left: '50%',
                        transform: 'translateX(-50%)',
                        backgroundColor: '#ffffff',
                        border: '1px solid #E2E8F0',
                        borderRadius: '14px',
                        boxShadow: '0 12px 30px rgba(0, 0, 0, 0.12)',
                        minWidth: cat.subCategories.length > 8 ? '480px' : '230px',
                        width: cat.subCategories.length > 8 ? '480px' : '230px',
                        zIndex: 10000,
                        padding: '10px 8px',
                        animation: 'navFadeIn 0.2s ease',
                        maxHeight: "420px",
                        overflowY: "auto",
                        overflowX: "hidden"
                      }}
                    >
                      <div style={{
                        display: cat.subCategories.length > 8 ? 'grid' : 'flex',
                        gridTemplateColumns: cat.subCategories.length > 8 ? 'repeat(2, 1fr)' : 'none',
                        flexDirection: cat.subCategories.length > 8 ? 'none' : 'column',
                        gap: '4px'
                      }}>
                        {cat.subCategories.map((sub) => {
                          const isAll = sub.startsWith("All");
                          const subFilterVal = isAll ? "All" : sub;
                          const isSubActive = isCatActive && (activeSubCategory === subFilterVal || (!activeSubCategory && isAll));

                          return (
                            <div
                              key={sub}
                              onClick={() => {
                                handleSelectCategory(cat.name, subFilterVal);
                                setHoveredCategory(null);
                              }}
                              style={{
                                padding: '9px 14px',
                                fontSize: '13.5px',
                                color: isSubActive ? '#A847F0' : '#334155',
                                fontWeight: isSubActive ? '700' : '500',
                                backgroundColor: isSubActive ? '#F9F5FF' : 'transparent',
                                borderRadius: '8px',
                                transition: 'all 0.15s ease',
                                cursor: 'pointer',
                                textAlign: 'left',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'space-between'
                              }}
                              onMouseEnter={(e) => {
                                if (!isSubActive) e.currentTarget.style.backgroundColor = '#F8FAFC';
                              }}
                              onMouseLeave={(e) => {
                                if (!isSubActive) e.currentTarget.style.backgroundColor = 'transparent';
                              }}
                            >
                              <span>{sub}</span>
                              {isSubActive && <span style={{ color: '#A847F0', fontSize: '12px' }}>✓</span>}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
              </div>
            );
          })}

        </div>
      </nav>

      {/* Mobile Subcategories Bottom Sheet Modal (Portaled directly to document.body) */}
      {hoveredCategory && (
        (() => {
          const selectedCatObj = categories.find(c => c.id === hoveredCategory);
          if (!selectedCatObj || !selectedCatObj.subCategories || selectedCatObj.subCategories.length === 0) return null;

          const modalContent = (
            <div
              className="d-block d-lg-none header-mobile-sheet-backdrop"
              style={{
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                width: '100vw',
                height: '100vh',
                backgroundColor: 'rgba(15, 23, 42, 0.65)',
                backdropFilter: 'blur(4px)',
                zIndex: 9999999,
                display: 'flex',
                alignItems: 'flex-end',
                justifyContent: 'center',
                animation: 'fadeIn 0.2s ease-out',
                pointerEvents: 'auto',
                touchAction: 'none'
              }}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                setHoveredCategory(null);
              }}
              onTouchEnd={(e) => {
                if (e.target === e.currentTarget) {
                  e.preventDefault();
                  e.stopPropagation();
                  setHoveredCategory(null);
                }
              }}
            >
              <div
                className="header-mobile-sheet-container"
                style={{
                  backgroundColor: '#ffffff',
                  borderTopLeftRadius: '24px',
                  borderTopRightRadius: '24px',
                  width: '100%',
                  maxWidth: '500px',
                  maxHeight: '75vh',
                  display: 'flex',
                  flexDirection: 'column',
                  boxShadow: '0 -10px 30px rgba(0, 0, 0, 0.25)',
                  overflow: 'hidden',
                  paddingBottom: '20px',
                  pointerEvents: 'auto',
                  touchAction: 'pan-y'
                }}
                onClick={(e) => {
                  e.stopPropagation();
                }}
                onTouchEnd={(e) => {
                  e.stopPropagation();
                }}
              >
                {/* Sheet Handle Indicator */}
                <div style={{ display: 'flex', justifyContent: 'center', padding: '10px 0 4px 0' }}>
                  <div style={{ width: '40px', height: '4px', backgroundColor: '#CBD5E1', borderRadius: '4px' }} />
                </div>

                {/* Sheet Header */}
                <div style={{
                  padding: '12px 20px 14px 20px',
                  borderBottom: '1px solid #F1F5F9',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between'
                }}>
                  <div>
                    <h6 style={{ margin: 0, fontWeight: '800', color: '#0F172A', fontSize: '17px' }}>
                      {selectedCatObj.name}
                    </h6>
                    <span style={{ fontSize: '12.5px', color: '#64748B' }}>Choose subcategory to browse items</span>
                  </div>
                  <button
                    type="button"
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      setHoveredCategory(null);
                    }}
                    style={{
                      border: 'none',
                      background: '#F1F5F9',
                      borderRadius: '50%',
                      width: '32px',
                      height: '32px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: '#64748B',
                      cursor: 'pointer',
                      fontSize: '18px',
                      fontWeight: '700'
                    }}
                  >
                    &times;
                  </button>
                </div>

                {/* Subcategories List */}
                <div
                  style={{
                    padding: '12px 16px',
                    overflowY: 'auto',
                    flex: 1,
                    WebkitOverflowScrolling: 'touch',
                    maxHeight: '60vh',
                    touchAction: 'pan-y'
                  }}
                  className="custom-scrollbar"
                >
                  {/* Option 1: All items in this category */}
                  <button
                    type="button"
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      handleSelectCategory(selectedCatObj.name, "All");
                      setHoveredCategory(null);
                    }}
                    onPointerDown={(e) => e.stopPropagation()}
                    onTouchStart={(e) => e.stopPropagation()}
                    style={{
                      width: '100%',
                      padding: '13px 16px',
                      borderRadius: '12px',
                      fontSize: '14.5px',
                      fontWeight: '700',
                      color: '#7C3AED',
                      backgroundColor: '#F5F3FF',
                      border: '1.5px solid #DDD6FE',
                      marginBottom: '8px',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      userSelect: 'none',
                      touchAction: 'manipulation',
                      textAlign: 'left'
                    }}
                  >
                    <span>All {selectedCatObj.name}</span>
                    <span style={{ fontSize: '16px' }}>&rarr;</span>
                  </button>

                  {/* Other subcategories */}
                  {selectedCatObj.subCategories.map((sub) => {
                    const isSelected = activeCategory === selectedCatObj.name && activeSubCategory === sub;
                    return (
                      <button
                        key={sub}
                        type="button"
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          handleSelectCategory(selectedCatObj.name, sub);
                          setHoveredCategory(null);
                        }}
                        onPointerDown={(e) => e.stopPropagation()}
                        onTouchStart={(e) => e.stopPropagation()}
                        style={{
                          width: '100%',
                          padding: '13px 16px',
                          borderRadius: '10px',
                          fontSize: '14px',
                          fontWeight: isSelected ? '700' : '500',
                          color: isSelected ? '#7C3AED' : '#334155',
                          backgroundColor: isSelected ? '#EDE9FE' : 'transparent',
                          border: isSelected ? '1px solid #DDD6FE' : 'none',
                          borderBottom: isSelected ? '1px solid #DDD6FE' : '1px solid #F8FAFC',
                          cursor: 'pointer',
                          marginBottom: '4px',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'space-between',
                          userSelect: 'none',
                          touchAction: 'manipulation',
                          textAlign: 'left'
                        }}
                      >
                        <span>{sub}</span>
                        {isSelected && <span style={{ color: '#7C3AED', fontWeight: '700' }}>✓</span>}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          );

          return typeof document !== 'undefined' ? createPortal(modalContent, document.body) : modalContent;
        })()
      )}

      {/* Mobile Category Menu (Portaled directly to document.body, opens on dropdown icon click) */}
      {isMobileCategoryMenuOpen && (() => {
        const modalContent = (
          <div
            className="d-block d-lg-none mobile-category-menu-backdrop"
            style={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              width: '100vw',
              height: '100vh',
              backgroundColor: 'rgba(15, 23, 42, 0.65)',
              backdropFilter: 'blur(4px)',
              zIndex: 9999999,
              display: 'flex',
              alignItems: 'flex-end',
              justifyContent: 'center',
              animation: 'fadeIn 0.2s ease-out',
              pointerEvents: 'auto',
              touchAction: 'none'
            }}
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              setIsMobileCategoryMenuOpen(false);
            }}
          >
            <div
              className="mobile-category-menu-container"
              style={{
                backgroundColor: '#ffffff',
                borderTopLeftRadius: '24px',
                borderTopRightRadius: '24px',
                width: '100%',
                maxWidth: '500px',
                maxHeight: '80vh',
                display: 'flex',
                flexDirection: 'column',
                boxShadow: '0 -10px 30px rgba(0, 0, 0, 0.25)',
                overflow: 'hidden',
                paddingBottom: '24px',
                pointerEvents: 'auto',
                touchAction: 'pan-y'
              }}
              onClick={(e) => e.stopPropagation()}
            >
              {/* Sheet Handle Indicator */}
              <div style={{ display: 'flex', justifyContent: 'center', padding: '10px 0 4px 0' }}>
                <div style={{ width: '40px', height: '4px', backgroundColor: '#CBD5E1', borderRadius: '4px' }} />
              </div>

              {/* Sheet Header */}
              <div style={{
                padding: '12px 20px 14px 20px',
                borderBottom: '1px solid #F1F5F9',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between'
              }}>
                <div>
                  <h6 style={{ margin: 0, fontWeight: '800', color: '#0F172A', fontSize: '17px' }}>
                    Shop by Category
                  </h6>
                  <span style={{ fontSize: '12.5px', color: '#64748B' }}>Select a category or subcategory to browse</span>
                </div>
                <button
                  type="button"
                  onClick={() => setIsMobileCategoryMenuOpen(false)}
                  style={{
                    border: 'none',
                    background: '#F1F5F9',
                    borderRadius: '50%',
                    width: '32px',
                    height: '32px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: '#64748B',
                    cursor: 'pointer',
                    fontSize: '18px',
                    fontWeight: '700'
                  }}
                >
                  &times;
                </button>
              </div>

              {/* Category Accordion List */}
              <div
                style={{
                  padding: '12px 16px',
                  overflowY: 'auto',
                  flex: 1,
                  WebkitOverflowScrolling: 'touch',
                  maxHeight: '65vh',
                  touchAction: 'pan-y'
                }}
                className="custom-scrollbar"
              >
                {categories.map((cat) => {
                  const normalizedCat = activeCategory === "Medicines" ? "Medicines & Cosmetics" : activeCategory;
                  const isCatActive = normalizedCat === cat.name;
                  const isExpanded = expandedMobileCat === cat.id;
                  const hasSubs = cat.subCategories && cat.subCategories.length > 0;

                  return (
                    <div
                      key={cat.id}
                      style={{
                        marginBottom: '8px',
                        borderRadius: '12px',
                        border: isCatActive ? '1.5px solid #DDD6FE' : '1px solid #E2E8F0',
                        overflow: 'hidden',
                        backgroundColor: isCatActive ? '#FAF5FF' : '#FFFFFF'
                      }}
                    >
                      {/* Main Category Row */}
                      <div
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'space-between',
                          padding: '12px 16px',
                          cursor: 'pointer',
                          backgroundColor: isCatActive ? '#F5F3FF' : '#FFFFFF',
                          transition: 'background-color 0.15s ease'
                        }}
                      >
                        {/* Category Name */}
                        <div
                          onClick={() => {
                            handleSelectCategory(cat.name, "All");
                            setIsMobileCategoryMenuOpen(false);
                          }}
                          style={{
                            flex: 1,
                            fontWeight: isCatActive ? '700' : '600',
                            color: isCatActive ? '#7C3AED' : '#1E293B',
                            fontSize: '14.5px',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px'
                          }}
                        >
                          <span>{cat.name}</span>
                          {isCatActive && (
                            <span style={{ fontSize: '11px', backgroundColor: '#7C3AED', color: '#FFFFFF', padding: '1px 6px', borderRadius: '10px' }}>
                              Active
                            </span>
                          )}
                        </div>

                        {/* Expand / Collapse Icon for Subcategories */}
                        {hasSubs ? (
                          <div
                            onClick={(e) => {
                              e.stopPropagation();
                              setExpandedMobileCat(isExpanded ? null : cat.id);
                            }}
                            style={{
                              padding: '6px 8px',
                              cursor: 'pointer',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              borderRadius: '6px',
                              backgroundColor: isExpanded ? '#EDE9FE' : 'transparent',
                              color: '#7C3AED'
                            }}
                          >
                            <FiChevronDown
                              size={17}
                              style={{
                                transition: 'transform 0.2s ease',
                                transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)'
                              }}
                            />
                          </div>
                        ) : (
                          <div
                            onClick={() => {
                              handleSelectCategory(cat.name, "All");
                              setIsMobileCategoryMenuOpen(false);
                            }}
                            style={{ color: '#94A3B8', fontSize: '15px', cursor: 'pointer' }}
                          >
                            &rarr;
                          </div>
                        )}
                      </div>

                      {/* Subcategories Accordion Content */}
                      {hasSubs && isExpanded && (
                        <div
                          style={{
                            padding: '8px 12px 12px 12px',
                            borderTop: '1px solid #F1F5F9',
                            backgroundColor: '#FFFFFF',
                            display: 'flex',
                            flexDirection: 'column',
                            gap: '4px'
                          }}
                        >
                          {/* All items option */}
                          <div
                            onClick={() => {
                              handleSelectCategory(cat.name, "All");
                              setIsMobileCategoryMenuOpen(false);
                            }}
                            style={{
                              padding: '9px 12px',
                              borderRadius: '8px',
                              fontSize: '13.5px',
                              fontWeight: '700',
                              color: '#7C3AED',
                              backgroundColor: '#F5F3FF',
                              border: '1px solid #DDD6FE',
                              cursor: 'pointer',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'space-between'
                            }}
                          >
                            <span>All {cat.name}</span>
                            <span>&rarr;</span>
                          </div>

                          {/* Specific subcategories */}
                          {cat.subCategories.map((sub) => {
                            const isSubActive = isCatActive && activeSubCategory === sub;
                            return (
                              <div
                                key={sub}
                                onClick={() => {
                                  handleSelectCategory(cat.name, sub);
                                  setIsMobileCategoryMenuOpen(false);
                                }}
                                style={{
                                  padding: '8px 12px',
                                  borderRadius: '8px',
                                  fontSize: '13.5px',
                                  fontWeight: isSubActive ? '700' : '500',
                                  color: isSubActive ? '#7C3AED' : '#334155',
                                  backgroundColor: isSubActive ? '#EDE9FE' : 'transparent',
                                  cursor: 'pointer',
                                  display: 'flex',
                                  alignItems: 'center',
                                  justifyContent: 'space-between',
                                  borderBottom: '1px solid #F8FAFC'
                                }}
                              >
                                <span>{sub}</span>
                                {isSubActive && <span style={{ color: '#7C3AED', fontWeight: '700' }}>✓</span>}
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        );

        return typeof document !== 'undefined' ? createPortal(modalContent, document.body) : modalContent;
      })()}

      <UnifiedAuthModalSeller
        isOpen={isLoginModalOpen}
        onClose={() => {
          setIsLoginModalOpen(false);
          // Optional: You could reload the window or refetch user state here if needed
          const storedUser = localStorage.getItem("user");
          const storedSeller = localStorage.getItem("seller");
          if (storedUser) setUser(JSON.parse(storedUser));
          if (storedSeller) {
            const parsedSeller = JSON.parse(storedSeller);
            const sellerName = parsedSeller.basicInformation?.shopName || parsedSeller.basicInformation?.contactPersonName || parsedSeller.name || "Seller";
            setUser({
              ...parsedSeller,
              name: sellerName,
              role: "seller"
            });
          }
        }}
      />

      <style>{`
        .header-top-container {
          display: flex;
          align-items: center;
          justify-content: space-between;
          width: 100%;
          gap: 20px;
        }
        .header-logo {
          flex-shrink: 0;
        }
        .header-search-wrapper {
          flex: 1;
          max-width: 550px;
          display: flex;
          align-items: center;
        }
        .header-search-form {
          flex: 1;
          display: flex;
          align-items: center;
          background-color: #F8FAFC;
          border: 1px solid #E2E8F0;
          border-radius: 50px;
          padding: 4px 6px 4px 16px;
          transition: all 0.3s ease;
        }
        .header-actions {
          display: flex;
          align-items: center;
          gap: 20px;
          flex-shrink: 0;
        }
        .header-category-nav-container {
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 40px;
          max-width: 1200px;
          margin: 0 auto;
        }
        @media (max-width: 767px) {
          .cart-page-search-hidden {
            display: none !important;
          }
          .cart-page-nav-hidden {
            display: none !important;
          }
          .header-top-container {
            flex-wrap: wrap !important;
            gap: 10px !important;
          }
          .header-logo {
            order: 1 !important;
          }
          .header-logo img {
            height: 38px !important;
          }
          .header-actions {
            order: 2 !important;
            gap: 10px !important;
          }
          .header-search-wrapper {
            order: 3 !important;
            max-width: 100% !important;
            width: 100% !important;
            flex: 0 0 100% !important;
            margin: 4px 0 0 0 !important;
            display: flex !important;
            align-items: center !important;
            gap: 8px !important;
          }
          .header-search-form {
            flex: 1 !important;
            width: auto !important;
            min-width: 0 !important;
            padding: 3px 4px 3px 14px !important;
          }
          .mobile-category-dropdown-btn {
            margin-left: 0 !important;
            flex-shrink: 0 !important;
          }
        }
        .header-category-icon-btn:hover {
          background-color: #F3E8FF !important;
        }
        .header-category-icon-btn:active {
          background-color: #EDE9FE !important;
        }
        @media (max-width: 991px) {
          .header-category-nav-bar {
            display: none !important;
          }
        }
        /* Custom visible scrollbar for dropdowns and sheets */
        .custom-dropdown-scroll::-webkit-scrollbar,
        .custom-scrollbar::-webkit-scrollbar {
          width: 5px;
          height: 5px;
          display: block !important;
        }
        .custom-dropdown-scroll::-webkit-scrollbar-track,
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #F1F5F9;
          border-radius: 6px;
        }
        .custom-dropdown-scroll::-webkit-scrollbar-thumb,
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #CBD5E1;
          border-radius: 6px;
        }
        .custom-dropdown-scroll::-webkit-scrollbar-thumb:hover,
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #A847F0;
        }
        .custom-dropdown-scroll {
          scrollbar-width: thin;
          scrollbar-color: #CBD5E1 #F1F5F9;
        }

        @keyframes navFadeIn {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes slideUp {
          from { transform: translateY(100%); }
          to { transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default HeaderShop;
